from odoo import _, api, fields, models
from odoo.exceptions import ValidationError


class PosConfig(models.Model):
    _inherit = "pos.config"

    analytic_account_id = fields.Many2one(
        comodel_name="account.analytic.account",
        string="Analytic Account",
        check_company=True,
        domain="[('company_id', 'in', [False, company_id])]",
        help=(
            "Applied at 100% to eligible profit and loss lines generated by this "
            "Point of Sale. Leave empty to keep the standard Odoo behavior."
        ),
    )

    @api.constrains("analytic_account_id", "company_id")
    def _check_analytic_account_company(self):
        for config in self:
            if (
                config.analytic_account_id.company_id
                and config.analytic_account_id.company_id != config.company_id
            ):
                raise ValidationError(
                    _(
                        "The analytic account must belong to the same company as "
                        "the Point of Sale."
                    )
                )
